import {CHARACTERS,WEAPONS,STATS,Game,freshSave,sanitizeSave,weaponById,isUnlocked,upgradeCost,attackCost,buyStat,buyAttack,colors} from './game.js';
import {Renderer} from './render.js';
const $=s=>document.querySelector(s),key='kurothos-tides-save-v1';
let save,saveError='',selected='ignara',starting={},game=null,ready=false,last=0,hudClock=0,weaponKey='',announcementUntil=0,toastTimer=0,sound=false,audio=null,lastSound=0;
try{const raw=localStorage.getItem(key);save=raw?sanitizeSave(JSON.parse(raw)):freshSave();}catch{save=freshSave();saveError='Your save could not be read. Progress will remain in this tab until saving works.';}
const renderer=new Renderer($('#world')),keys=new Set(),modal=$('#modal');
function persist(){try{localStorage.setItem(key,JSON.stringify(save));saveError='';return true;}catch{saveError='Saving is unavailable. Keep this tab open to retain your progress.';$('#save-notice').textContent=saveError;return false;}}
function timeText(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0');}
function toast(text){$('#toast').textContent=text;$('#toast').style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.opacity=0,3000);}
function tone(freq=400,length=.06,type='sine',volume=.025){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.5),audio.currentTime+length);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+length);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+length);}catch{sound=false;}}
function renderWallet(){$('#wallet').textContent=save.gold.toLocaleString()+' gold';$('#record').textContent=save.runs?`${save.wins} victories · Best survival ${timeText(save.best)}`:'No voyages completed';$('#save-notice').textContent=saveError;}
function roster(){const parent=$('#roster');parent.replaceChildren();CHARACTERS.forEach((c,i)=>{const unlocked=isUnlocked(save,c.id),b=document.createElement('button');b.className='character-card'+(selected===c.id?' selected':'')+(!unlocked?' locked':'');b.style.setProperty('--glow',c.color);b.setAttribute('aria-pressed',selected===c.id);b.setAttribute('aria-label',c.name+(unlocked?', '+c.element:', defeat Naia to unlock'));b.innerHTML=`<span class="card-mark">${!unlocked?'LOCKED':selected===c.id?'◆':''}</span><div class="character-copy"><strong>${c.name}</strong><span>${c.element==='steel'?'Katana':c.element==='tide'?'Tentacles':c.element}</span></div>`;if(ready)b.insertBefore(renderer.portrait(i),b.querySelector('.character-copy'));b.onclick=()=>{selected=c.id;tone(280);renderMenu();};parent.appendChild(b);});}
function loadout(){const c=CHARACTERS.find(c=>c.id===selected),meta=save.characters[selected],unlocked=isUnlocked(save,selected);const opts=meta.unlocked.filter(id=>isUnlocked(save,weaponById(id).owner));if(!opts.includes(starting[selected]))starting[selected]=opts[0];const w=weaponById(starting[selected]);
 $('#loadout').innerHTML=`<div><span class="eyebrow" style="color:${c.color}">${c.title}</span><h3>${c.name}</h3><p class="character-description">${c.description}</p><div class="trait">${c.trait}</div><div class="stats-line"><span><b>${c.hp+meta.health*15}</b>Health</span><span><b>${Math.round(c.damage*(1+meta.attack*.08)*100)}%</b>Damage</span><span><b>${opts.length}</b>Attacks in pool</span></div></div><div><label for="starting-weapon">STARTING ATTACK</label><select id="starting-weapon" ${!unlocked?'disabled':''}>${opts.map(id=>`<option value="${id}" ${id===starting[selected]?'selected':''}>${weaponById(id).name} · ${weaponById(id).element}</option>`).join('')}</select><p class="weapon-description">${w?.desc||'Defeat Naia to claim her power.'}</p><p class="weapon-description">Choose one to begin. Build up to six attacks during the run.</p></div><div class="departure"><button class="primary" id="begin" ${!unlocked||!ready?'disabled':''}>${!ready?'Preparing the coast…':unlocked?'Enter the coast':'Defeat Naia to unlock'}</button><span class="quiet">${unlocked?'05:00 · Drowned Warden<br>10:00 · Mourning Siren<br>15:00 · Naia, the Crimson Tide':'Win a run with any survivor to unlock Naia and her attacks.'}</span></div>`;
 $('#starting-weapon').onchange=e=>{starting[selected]=e.target.value;loadout();};$('#begin').onclick=start;
}
function renderShop(){const c=CHARACTERS.find(c=>c.id===selected),meta=save.characters[selected];const parent=$('#shop-roster');parent.replaceChildren();for(const ch of CHARACTERS){const b=document.createElement('button');b.textContent=ch.name;b.className=selected===ch.id?'selected':'';b.onclick=()=>{selected=ch.id;renderMenu();};parent.appendChild(b);}
 if(!isUnlocked(save,selected)){$('#shop-content').innerHTML='<div class="shop-item"><h3>Naia awaits at the end of the coast.</h3><p>Win a run to unlock her as a survivor and make her attacks available for purchase.</p></div>';return;}
 $('#shop-content').innerHTML=`<h3 class="shop-section-title">${c.name} · Permanent growth</h3><div class="shop-grid">${['health','attack'].map(type=>{const cost=upgradeCost(save,selected,type),level=meta[type];return `<article class="shop-item"><span class="element">${level} / 10 upgrades</span><h3>${type==='health'?'Endurance':'Power'}</h3><p>${type==='health'?'+15 maximum health for every run. Current bonus: +'+level*15+' health.':'+8% base damage for every run. Current bonus: +'+level*8+'% damage.'}</p><button data-stat="${type}" ${level>=10||save.gold<cost?'disabled':''}>${level>=10?'Maximum rank':'Improve · '+cost+' gold'}</button></article>`;}).join('')}<article class="shop-item"><span class="element">${meta.unlocked.length} / 15 attacks unlocked</span><h3>Borrowed power</h3><p>Each attack you buy becomes a starting attack choice and joins ${c.name}’s level-up pool. Purchases apply to ${c.name}.</p><span class="owned-label">Your three native attacks are unlocked.</span></article></div><h3 class="shop-section-title">Attacks</h3><div class="shop-grid">${WEAPONS.map(w=>{const owned=meta.unlocked.includes(w.id),locked=!isUnlocked(save,w.owner);return `<article class="shop-item ${owned?'owned':''}" style="--ec:${colors[w.element]}"><span class="element">${w.element} · ${CHARACTERS.find(c=>c.id===w.owner).name}</span><h3>${w.name}</h3><p>${w.desc}</p>${owned?'<span class="owned-label">Unlocked · Starting choice + level-up pool</span>':`<button data-attack="${w.id}" ${locked||save.gold<attackCost(w)?'disabled':''}>${locked?'Defeat Naia to unlock':'Unlock · '+attackCost(w)+' gold'}</button>`}</article>`;}).join('')}</div>`;
 document.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{if(buyStat(save,selected,b.dataset.stat)){persist();tone(500,.15);toast('Permanent upgrade purchased for '+c.name);renderMenu();}});document.querySelectorAll('[data-attack]').forEach(b=>b.onclick=()=>{if(buyAttack(save,selected,b.dataset.attack)){persist();tone(650,.15);toast(weaponById(b.dataset.attack).name+' unlocked for '+c.name);renderMenu();}});
}
function renderMenu(){renderWallet();roster();loadout();renderShop();}
function tab(which){$('#venture').hidden=which!=='venture';$('#sanctum').hidden=which!=='sanctum';$('#venture-tab').classList.toggle('active',which==='venture');$('#sanctum-tab').classList.toggle('active',which==='sanctum');}
$('#venture-tab').onclick=()=>tab('venture');$('#sanctum-tab').onclick=()=>tab('sanctum');
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent='Sound: '+(sound?'on':'off');$('#sound').setAttribute('aria-label',sound?'Disable sound':'Enable sound');tone(550,.12);};
function openModal(html){$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal();requestAnimationFrame(()=>$('#modal-body button:not(:disabled)')?.focus());}
function start(){if(!ready||!isUnlocked(save,selected))return;keys.clear();game=new Game(selected,starting[selected],save);weaponKey='';$('#menu').hidden=true;$('#hud').hidden=false;if(modal.open)modal.close();document.body.style.overflow='hidden';announcementUntil=performance.now()+3500;$('#announcement').textContent='SURVIVE THE COAST';$('#announcement').style.opacity=1;last=performance.now();hud();tone(160,.3,'triangle');}
function hud(){if(!game)return;const g=game;$('#hud-name').textContent=g.character.name;$('#health-fill').style.width=(g.hp/g.maxHp*100)+'%';$('#health-label').textContent=Math.ceil(g.hp)+' / '+g.maxHp;$('#timer').textContent=timeText(g.time);$('#phase').textContent=g.finalSpawned?'DEFEAT NAIA':g.time>=600?'THE CRIMSON TIDE RISES':g.time>=300?'THE COAST REMEMBERS':'THE COAST AWAKENS';$('#kill-count').textContent='✧ '+g.kills;$('#run-gold').textContent='◆ '+Math.floor(g.gold);$('#xp-fill').style.width=(Math.min(1,g.xp/g.nextXp)*100)+'%';$('#level-label').textContent='LEVEL '+g.level;
 const wk=g.weapons.map(w=>w.id+w.level).join();if(wk!==weaponKey){weaponKey=wk;$('#weapons').innerHTML=g.weapons.map(w=>{const def=weaponById(w.id);return `<div class="weapon-slot" title="${def.name} · Rank ${w.level} / 5" style="--ec:${colors[def.element]}"><strong>${def.symbol}</strong><span>${w.level} / 5</span></div>`;}).join('');}
 const boss=game.enemies.find(e=>e.type==='final'&&e.hp>0)||game.enemies.find(e=>e.type==='mini'&&e.hp>0);$('#boss-hud').hidden=!boss;if(boss){$('#boss-name').textContent=boss.type==='final'?'NAIA · THE CRIMSON TIDE':boss.stage===1?'THE DROWNED WARDEN':'THE MOURNING SIREN';$('#boss-fill').style.width=(boss.hp/boss.maxHp*100)+'%';}
}
function levelup(){const g=game;if(g.state!=='levelup')return;tone(700,.3,'sine');openModal(`<div class="modal-heading"><span class="eyebrow">LEVEL ${g.level}</span><h2>Claim your power</h2><p>Choose one upgrade. The coast waits.</p></div><div class="choices">${g.choices.map((ch,i)=>{const w=ch.type==='weapon'?weaponById(ch.id):STATS.find(s=>s.id===ch.id);const color=ch.type==='weapon'?colors[w.element]:'#dbbd7a';return `<button class="upgrade-card" data-choice="${i}" style="--ec:${color}"><span class="upgrade-icon">${w.symbol}</span><span class="element">${ch.type==='weapon'?(ch.rank===1?'NEW ATTACK':w.element+' · UPGRADE'):'SURVIVOR · STAT'}</span><h3>${w.name}</h3><p>${ch.type==='weapon'?(ch.rank===1?w.desc:'+45% base damage, faster attacks'+(w.radius?', and greater reach.':'.')):w.desc}</p><small>${i+1} · ${ch.type==='weapon'?'Rank '+ch.rank+' / 5':'Upgrade '+ch.rank}</small></button>`;}).join('')}</div>`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.choice)));}
function choose(i){if(!game||game.state!=='levelup')return;if(game.choose(i)){modal.close();keys.clear();hud();processEvents();}}
function pause(){if(!game||game.state!=='playing')return;game.state='paused';keys.clear();openModal(`<div class="modal-heading"><span class="eyebrow">THE COAST CAN WAIT</span><h2>Paused</h2><p>${game.character.name} · ${timeText(game.time)} · Level ${game.level}</p></div><p class="quiet" style="text-align:center">Move with WASD or the arrow keys. Your attacks aim and fire on their own.<br>Collect experience shards to gain levels. Avoid pink projectiles and marked circles.</p><div class="modal-actions"><button class="primary" id="resume">Resume</button><button class="secondary" id="retreat">End run &amp; keep gold</button></div>`);$('#resume').onclick=resume;$('#retreat').onclick=()=>{openModal('<div class="modal-heading"><h2>Leave the coast?</h2><p>Your gold is kept. This run ends.</p></div><div class="modal-actions"><button class="primary" id="stay">Keep fighting</button><button class="secondary" id="leave">End this run</button></div>');$('#stay').onclick=resume;$('#leave').onclick=()=>{game.state='abandoned';end();};};}
function resume(){if(game?.state==='paused'){game.state='playing';keys.clear();last=performance.now();modal.close();}}
function end(){if(!game||!['won','dead','abandoned'].includes(game.state))return;const g=game,firstWin=g.state==='won'&&save.wins===0;g.settle(save);persist();hud();tone(g.state==='won'?600:110,.5,'triangle');openModal(`<div class="modal-heading"><span class="eyebrow">${g.state==='won'?'THE COAST IS YOURS':g.state==='abandoned'?'A STRATEGIC RETREAT':'THE TIDE TAKES ITS DUE'}</span><h2>${g.state==='won'?'Naia has fallen':g.state==='abandoned'?'Return to the Sanctum':'Your voyage ends'}</h2><p>${g.state==='won'?'Your victory is written into Kurothos.':'Your gold remains. Return with greater power.'}</p></div><div class="result-stats"><div><b>${timeText(g.time)}</b><span>Survived</span></div><div><b>${g.kills}</b><span>Enemies defeated</span></div><div><b>+${Math.floor(g.gold)}</b><span>Gold earned</span></div></div>${firstWin?'<div class="unlock-banner">Naia is unlocked. Her tentacle attacks can be purchased by every survivor.</div>':''}${saveError?'<p class="notice">'+saveError+'</p>':''}<div class="modal-actions"><button class="primary" id="return">Return to the Sanctum</button><button class="secondary" id="again">New run</button></div>`);$('#return').onclick=()=>{game=null;modal.close();$('#menu').hidden=false;$('#hud').hidden=true;document.body.style.overflow='';renderMenu();tab('sanctum');};$('#again').onclick=()=>{renderMenu();game=null;modal.close();$('#menu').hidden=false;$('#hud').hidden=true;document.body.style.overflow='';tab('venture');};}
function processEvents(){if(!game)return;const ev=game.events.splice(0);for(const e of ev){if(e.type==='levelup')levelup();else if(e.type==='end')end();else if(e.type==='announce'){$('#announcement').textContent=e.text;$('#announcement').style.opacity=1;announcementUntil=performance.now()+4000;}else if(e.type==='hurt')tone(70,.13,'sawtooth',.04);else if(e.type==='heal')tone(550,.1);else if(e.type==='boss')tone(80,.6,'triangle');else if(e.type==='cast'&&performance.now()-lastSound>180){lastSound=performance.now();tone(e.element==='fire'?130:e.element==='ice'?800:e.element==='steel'?1000:330,.045,'triangle',.009);}}}
$('#pause').onclick=pause;modal.addEventListener('cancel',e=>{e.preventDefault();if(game?.state==='paused')resume();});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(game&&['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','escape','1','2','3'].includes(k))e.preventDefault();if(e.repeat&&k==='escape')return;if(k==='escape'){if(game?.state==='playing')pause();else if(game?.state==='paused')resume();}else if(game?.state==='levelup'&&['1','2','3'].includes(k))choose(Number(k)-1);else keys.add(k);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();pause();}});
let pointer=null;$('#world').addEventListener('pointerdown',e=>{if(game?.state==='playing'){pointer={id:e.pointerId,startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY};$('#world').setPointerCapture(e.pointerId);}});$('#world').addEventListener('pointermove',e=>{if(pointer?.id===e.pointerId){pointer.x=e.clientX;pointer.y=e.clientY;}});for(const event of ['pointerup','pointercancel'])$('#world').addEventListener(event,()=>pointer=null);$('#world').style.touchAction='none';
function loop(t){const dt=Math.min(.05,(t-(last||t))/1000);last=t;if(game?.state==='playing'){const input={x:Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft')),y:Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'))};if(pointer){input.x=(pointer.x-pointer.startX)/35;input.y=(pointer.y-pointer.startY)/35;if(Math.hypot(input.x,input.y)<.2){input.x=0;input.y=0;}}game.step(dt,input);processEvents();}renderer.frame(game);if(game&&(t-hudClock>100)){hud();hudClock=t;}if(t>announcementUntil)$('#announcement').style.opacity=0;requestAnimationFrame(loop);}
renderMenu();renderer.load().then(()=>{ready=true;renderMenu();requestAnimationFrame(loop);}).catch(error=>{$('#save-notice').textContent='The character art could not load. Reload this page to try again.';console.error(error);});
